<?php
declare(strict_types=1);require_once __DIR__.'/_helper.php';home_visit_require_access();if(!home_visit_can_manage()){http_response_code(403);exit('Akses Home Visit ditolak.');}$id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT hv.*,s.nis,s.nisn,s.nama siswa_nama,g.nama petugas,tp.nama tapel FROM home_visit hv JOIN siswa s ON s.id=hv.siswa_id LEFT JOIN guru g ON g.id=hv.petugas_id LEFT JOIN tahun_pelajaran tp ON tp.id=hv.tahun_pelajaran_id WHERE hv.id=? LIMIT 1");$st->execute([$id]);$r=$st->fetch();if(!$r)exit('Data Home Visit tidak ditemukan.');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();$status=(string)($_POST['status']??$r['status']);$hasil=trim((string)($_POST['hasil']??''));$cat=trim((string)($_POST['catatan']??''));$tl=trim((string)($_POST['tindak_lanjut']??''));$tp=$_POST['tanggal_pelaksanaan']?:null;$w=$_POST['waktu']?:null;if(!in_array($status,['direncanakan','dilaksanakan','ditunda','dibatalkan'],true))$status=$r['status'];if(!home_visit_status_can_change((string)$r['status'],$status)){$status=$r['status'];}$u=$pdo->prepare("UPDATE home_visit SET tanggal_pelaksanaan=?,waktu=?,hasil=?,catatan=?,tindak_lanjut=?,status=?,updated_at=NOW() WHERE id=?");$u->execute([$tp,$w,$hasil,$cat,$tl,$status,$id]);$aksi=$status!==$r['status']?'STATUS':'UPDATE';$ket=$status!==$r['status']?'Mengubah status Home Visit: '.home_visit_status_label((string)$r['status']).' → '.home_visit_status_label($status):'Memperbarui Home Visit';home_visit_audit($pdo,$aksi,$id,$ket);header('Location: '.BASE_URL.'home_visit/detail.php?id='.$id);exit;}$page_title='Detail Home Visit';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';?><main class="main"><header class="topbar"><div class="topbar-title">Detail Home Visit</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content home-visit-module"><div class="card" style="max-width:1000px;margin:auto"><div class="section-title"><div><h2><i class="bi bi-house-door-fill"></i> <?=e($r['siswa_nama'])?></h2><p><?=e($r['nis'])?> · Tapel <?=e($r['tapel']??'-')?></p></div><div style="display:flex;gap:8px"><a class="btn btn-secondary" href="<?=BASE_URL?>home_visit/index.php">Kembali</a></div></div><div class="row g-3"><div class="col-md-6"><div class="p-3 bg-light rounded"><strong>Alasan / Permasalahan</strong><div style="white-space:pre-wrap;margin-top:8px"><?=e($r['alasan'])?></div></div></div><div class="col-md-6"><div class="p-3 bg-light rounded"><strong>Tujuan</strong><div style="white-space:pre-wrap;margin-top:8px"><?=e($r['tujuan'])?></div></div></div></div><hr><form method="post"><?=csrf_field()?><div class="row g-3"><div class="col-md-3"><label class="form-label">Tanggal Pelaksanaan</label><input type="date" name="tanggal_pelaksanaan" class="form-control" value="<?=e($r['tanggal_pelaksanaan']??'')?>"></div><div class="col-md-2"><label class="form-label">Waktu</label><input type="time" name="waktu" class="form-control" value="<?=e($r['waktu']??'')?>"></div><div class="col-md-3"><label class="form-label">Status</label><select name="status" class="form-control"><?php foreach(home_visit_status_transitions((string)$r['status']) as $v):?><option value="<?=$v?>" <?=$r['status']===$v?'selected':''?>><?=e(home_visit_status_label($v))?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Petugas</label><input class="form-control" value="<?=e($r['petugas']??'Belum ditentukan')?>" disabled></div><div class="col-md-6"><label class="form-label">Hasil Kunjungan</label><textarea name="hasil" class="form-control" rows="5"><?=e($r['hasil']??'')?></textarea></div><div class="col-md-6"><label class="form-label">Catatan</label><textarea name="catatan" class="form-control" rows="5"><?=e($r['catatan']??'')?></textarea></div><div class="col-12"><label class="form-label">Tindak Lanjut</label><textarea name="tindak_lanjut" class="form-control" rows="4"><?=e($r['tindak_lanjut']??'')?></textarea></div></div><div style="margin-top:18px;display:flex;justify-content:flex-end"><button class="btn btn-primary"><i class="bi bi-save"></i> Simpan Perubahan</button></div></form></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';?>
